  1904  private uint64_t
  1905  file_strncmp(const char *s1, const char *s2, size_t len, uint32_t flags)
  1906  {
  1907          /*
  1908           * Convert the source args to unsigned here so that (1) the
  1909           * compare will be unsigned as it is in strncmp() and (2) so
  1910           * the ctype functions will work correctly without extra
  1911           * casting.
  1912           */
  1913          const unsigned char *a = RCAST(const unsigned char *, s1);
  1914          const unsigned char *b = RCAST(const unsigned char *, s2);
  1915          uint32_t ws = flags & (STRING_COMPACT_WHITESPACE |
  1916              STRING_COMPACT_OPTIONAL_WHITESPACE);
  1917          const unsigned char *eb = b + (ws ? strlen(s2) : len);
  1918          uint64_t v;
  1919
  1920          /*
  1921           * What we want here is v = strncmp(s1, s2, len),
  1922           * but ignoring any nulls.
  1923           */
  1924          v = 0;
  1925          if (0L == flags) { /* normal string: do it fast */
  1926                  while (len-- > 0)
  1927                          if ((v = *b++ - *a++) != '\0')
  1928                                  break;
  1929          }
  1930          else { /* combine the others */
  1931                  while (len-- > 0) {
  1932                          if (b >= eb) {
  1933                                  v = 1;
  1934                                  break;
  1935                          }
  1936                          if ((flags & STRING_IGNORE_LOWERCASE) &&
  1937                              islower(*a)) {
  1938                                  if ((v = tolower(*b++) - *a++) != '\0')
  1939                                          break;
  1940                          }
  1941                          else if ((flags & STRING_IGNORE_UPPERCASE) &&
  1942                              isupper(*a)) {
  1943                                  if ((v = toupper(*b++) - *a++) != '\0')
  1944                                          break;
  1945                          }
  1946                          else if ((flags & STRING_COMPACT_WHITESPACE) &&
  1947                              isspace(*a)) {
  1948                                  a++;
  1949                                  if (isspace(*b++)) {
  1950                                          if (!isspace(*a))
  1951                                                  while (b < eb && isspace(*b))
  1952                                                          b++;
  1953                                  }
  1954                                  else {
  1955                                          v = 1;
  1956                                          break;
  1957                                  }
  1958                          }
  1959                          else if ((flags & STRING_COMPACT_OPTIONAL_WHITESPACE) &&
  1960                              isspace(*a)) {
  1961                                  a++;
  1962                                  while (b < eb && isspace(*b))
  1963                                          b++;
  1964                          }
  1965                          else {
  1966                                  if ((v = *b++ - *a++) != '\0')
  1967                                          break;
  1968                          }
  1969                  }
  1970          }
  1971          return v;
  1972  }
