  1974  private uint64_t
  1975  file_strncmp16(const char *a, const char *b, size_t len, uint32_t flags)
  1976  {
  1977          /*
  1978           * XXX - The 16-bit string compare probably needs to be done
  1979           * differently, especially if the flags are to be supported.
  1980           * At the moment, I am unsure.
  1981           */
  1982          flags = 0;
  1983          return file_strncmp(a, b, len, flags);
